<?php
require 'config.php';require 'auth.php';require 'helpers.php';require_login();$error='';$courtId=(int)($_POST['court_id']??$_GET['court_id']??0);$date=$_POST['booking_date']??$_GET['date']??date('Y-m-d');$slotId=(int)($_POST['time_slot_id']??$_GET['slot_id']??0);$courts=$conn->query('SELECT c.id,c.court_name,f.facility_name,f.price_per_hour FROM courts c JOIN facilities f ON f.id=c.facility_id WHERE c.is_active=1 AND f.is_active=1 ORDER BY f.facility_name,c.court_name')->fetch_all(MYSQLI_ASSOC);
if($_SERVER['REQUEST_METHOD']==='POST'){$purpose=trim($_POST['purpose']??'');$participants=(int)($_POST['participants']??0);if($courtId<1||$slotId<1||!valid_date($date)||$date<date('Y-m-d')||$purpose===''||$participants<1||$participants>50){$error='Provide a valid court, future slot, purpose and participant count (1-50).';}else{$conn->begin_transaction();$stmt=$conn->prepare('SELECT c.id,f.price_per_hour,ts.start_time FROM courts c JOIN facilities f ON f.id=c.facility_id JOIN time_slots ts ON ts.id=? WHERE c.id=? AND c.is_active=1 AND f.is_active=1 FOR UPDATE');$stmt->bind_param('ii',$slotId,$courtId);$stmt->execute();$selected=$stmt->get_result()->fetch_assoc();$stmt=$conn->prepare("SELECT id FROM bookings WHERE court_id=? AND booking_date=? AND time_slot_id=? AND status='confirmed' FOR UPDATE");$stmt->bind_param('isi',$courtId,$date,$slotId);$stmt->execute();$conflict=$stmt->get_result()->fetch_assoc();$stmt=$conn->prepare('SELECT id FROM closures WHERE court_id=? AND closure_date=? AND (time_slot_id IS NULL OR time_slot_id=?) FOR UPDATE');$stmt->bind_param('isi',$courtId,$date,$slotId);$stmt->execute();$closure=$stmt->get_result()->fetch_assoc();if(!$selected||booking_has_started($date,$selected['start_time'])||$conflict||$closure){$conn->rollback();$error='That slot is no longer available. Please choose another.';}else{$uid=current_user_id();$price=(float)$selected['price_per_hour'];$stmt=$conn->prepare("INSERT INTO bookings(user_id,court_id,time_slot_id,booking_date,purpose,participants,total_price,status) VALUES(?,?,?,?,?,?,?,'confirmed')");$stmt->bind_param('iiissid',$uid,$courtId,$slotId,$date,$purpose,$participants,$price);if($stmt->execute()){$id=$stmt->insert_id;$conn->commit();header('Location: confirmation.php?id='.$id);exit;}$conn->rollback();$error='The slot was just taken. Please choose another.';}}}
$pageTitle='Book a Facility';require 'partials/header.php';?>
<div class="form-card"><h1>Book a Sports Facility</h1><p>Choose one available one-hour slot.</p><?php if($error):?><p class="alert alert-error"><?=htmlspecialchars($error)?></p><?php endif;?><form method="post"><label>Court / Area <span class="required-mark">*</span><select name="court_id" id="court" required><option value="">-- Select --</option><?php foreach($courts as $c):?><option value="<?=(int)$c['id']?>" <?=$courtId===(int)$c['id']?'selected':''?>><?=htmlspecialchars($c['facility_name'].' - '.$c['court_name'])?> (RM<?=number_format($c['price_per_hour'],2)?>)</option><?php endforeach;?></select></label><label>Date <span class="required-mark">*</span><input type="date" id="booking-date" name="booking_date" min="<?=date('Y-m-d')?>" value="<?=htmlspecialchars($date)?>" required></label><label>Time Slot <span class="required-mark">*</span><select name="time_slot_id" id="slot" data-selected="<?=$slotId?>" required><option value="">-- Select court and date --</option></select></label><label>Purpose <span class="required-mark">*</span><input name="purpose" maxlength="180" value="<?=htmlspecialchars($_POST['purpose']??'Training / recreation')?>" required></label><label>Participants <span class="required-mark">*</span><input type="number" name="participants" min="1" max="50" value="<?=(int)($_POST['participants']??1)?>" required></label><button>Confirm Booking</button> <a class="btn btn-secondary" href="schedule.php">Back</a></form></div>
<script>const c=document.getElementById('court'),d=document.getElementById('booking-date'),s=document.getElementById('slot');async function load(){if(!c.value||!d.value)return;s.innerHTML='<option>Loading...</option>';try{const r=await fetch(`slot_availability.php?court_id=${c.value}&date=${d.value}`),rows=await r.json(),wanted=s.dataset.selected;s.innerHTML='<option value="">-- Select available time --</option>'+rows.map(x=>`<option value="${x.id}" ${x.available?'':'disabled'} ${String(x.id)===wanted?'selected':''}>${x.label}${x.available?'':' - Unavailable'}</option>`).join('');s.dataset.selected='';}catch(e){s.innerHTML='<option>Could not load availability</option>';}}c.addEventListener('change',load);d.addEventListener('change',load);load();</script><?php require 'partials/footer.php';?>

